@php($cover=P::media($item['cover']??$item['photo']??$item['image']??null))
<article class="content-card {{ $resource==='board-members'?'board-member-card':'' }} {{ $resource==='albums'?'album-card':'' }} {{ !$cover?'without-image':'' }}"><a href="{{ P::path($resource,$item) }}">@if($cover)<div class="card-image"><img src="{{ $cover }}" alt="{{ P::title($item) }}" loading="lazy">@if($resource==='albums')<span class="image-label">{{ P::t('آلبوم تصاویر') }}</span>@endif</div>@endif<div class="card-copy">@if($when=P::date($item['published_at']??$item['event_date']??$item['starts_at']??null))<time>{{ $when }}</time>@endif<h3>{{ P::title($item) }}</h3>@if($excerpt=$item['excerpt']??$item['description']??$item['position']??$item['partner']??'')<p>{{ $excerpt }}</p>@endif<span class="read-more">{{ P::t('مشاهده جزئیات') }}<i data-lucide="chevron-left"></i></span></div></a>@if($resource==='board-members'&&P::href($item['contact_url']??null))<a class="board-contact-link" href="{{ P::href($item['contact_url']) }}" target="_blank" rel="noopener noreferrer"><i data-lucide="message-circle"></i>{{ $item['contact_label']??P::t('راه ارتباطی') }}</a>@endif</article>